1	//! Component detection: FC annotation, forwardRef, HOC-wrapped, ForwardRefExoticComponent.
2	
3	use std::collections::BTreeMap;
4	
5	use camino::Utf8Path;
6	use oxc_ast::ast::*;
7	
8	use crate::types::{CollectedTypeAlias, ComponentMapping, DetectionRule, DiagnosticCode};
9	
10	use super::evidence::{FunctionShape, Scope, renders};
11	use super::{ReactApi, SourceDataCollector, is_pascal_case};
12	
13	/// One layer of the wrappers TypeScript erases from a value.
14	enum Wrapper<'b, 'a> {
15	    /// Parentheses, `satisfies` or `!`: the value and its type pass through.
16	    Transparent(&'b Expression<'a>),
17	    /// `as` or `<T>x`: the value passes through, its type is replaced.
18	    Asserted(&'b Expression<'a>),
19	    /// `f<T>`: the value passes through with its type arguments given.
20	    Instantiation(&'b TSInstantiationExpression<'a>),
21	}
22	
23	/// The wrapper `expr` is, if it is one. The one list of what a wrapper is, and exhaustive so that a new expression kind
24	/// in an OXC release has to be placed here before it compiles.
25	fn wrapper<'a, 'b>(expr: &'b Expression<'a>) -> Option<Wrapper<'b, 'a>> {
26	    match expr {
27	        Expression::ParenthesizedExpression(inner) => Some(Wrapper::Transparent(&inner.expression)),
28	        Expression::TSSatisfiesExpression(inner) => Some(Wrapper::Transparent(&inner.expression)),
29	        Expression::TSNonNullExpression(inner) => Some(Wrapper::Transparent(&inner.expression)),
30	        Expression::TSAsExpression(inner) => Some(Wrapper::Asserted(&inner.expression)),
31	        Expression::TSTypeAssertion(inner) => Some(Wrapper::Asserted(&inner.expression)),
32	        Expression::TSInstantiationExpression(inner) => Some(Wrapper::Instantiation(inner)),
33	        Expression::BooleanLiteral(_)
34	        | Expression::NullLiteral(_)
35	        | Expression::NumericLiteral(_)
36	        | Expression::BigIntLiteral(_)
37	        | Expression::RegExpLiteral(_)
38	        | Expression::StringLiteral(_)
39	        | Expression::TemplateLiteral(_)
40	        | Expression::Identifier(_)
41	        | Expression::Super(_)
42	        | Expression::ArrayExpression(_)
43	        | Expression::ArrowFunctionExpression(_)
44	        | Expression::AssignmentExpression(_)
45	        | Expression::AwaitExpression(_)
46	        | Expression::BinaryExpression(_)
47	        | Expression::CallExpression(_)
48	        | Expression::ChainExpression(_)
49	        | Expression::ClassExpression(_)
50	        | Expression::ConditionalExpression(_)
51	        | Expression::FunctionExpression(_)
52	        | Expression::ImportExpression(_)
53	        | Expression::LogicalExpression(_)
54	        | Expression::NewExpression(_)
55	        | Expression::ObjectExpression(_)
56	        | Expression::SequenceExpression(_)
57	        | Expression::TaggedTemplateExpression(_)
58	        | Expression::ThisExpression(_)
59	        | Expression::UnaryExpression(_)
60	        | Expression::UpdateExpression(_)
61	        | Expression::YieldExpression(_)
62	        | Expression::PrivateInExpression(_)
63	        | Expression::ImportMeta(_)
64	        | Expression::NewTarget(_)
65	        | Expression::JSXElement(_)
66	        | Expression::JSXFragment(_)
67	        | Expression::V8IntrinsicExpression(_)
68	        | Expression::ComputedMemberExpression(_)
69	        | Expression::StaticMemberExpression(_)
70	        | Expression::PrivateFieldExpression(_) => None,
71	    }
72	}
73	
74	/// A value beneath its wrappers: component libraries cast a forwardRef or HOC call to a hand-rolled component type
75	/// (Fluent UI: "required due to lack of distributive union to support unions on @types/react"), or check it with
76	/// `satisfies`. An instantiation is kept: `const X = Base<P>` is not `Base`, and reading it as `Base` drops `P`.
77	pub(super) fn peel_expr<'a, 'b>(mut expr: &'b Expression<'a>) -> &'b Expression<'a> {
78	    loop {
79	        expr = match wrapper(expr) {
80	            Some(Wrapper::Transparent(inner) | Wrapper::Asserted(inner)) => inner,
81	            Some(Wrapper::Instantiation(_)) | None => return expr,
82	        };
83	    }
84	}
85	
86	/// An expression beneath every wrapper, instantiations included, and the type arguments an instantiation among them
87	/// gave it.
88	#[derive(Clone, Copy)]
89	pub(super) struct Peeled<'b, 'a> {
90	    pub(super) expr: &'b Expression<'a>,
91	    /// The outermost instantiation's type arguments, unless an assertion above it replaced its type: `(f<T>)` and
92	    /// `(f<T>)!` give `T`; `(f<T> as G)` gives none, as the value then has type `G`.
93	    pub(super) type_arguments: Option<&'b TSTypeParameterInstantiation<'a>>,
94	}
95	
96	/// See [`Peeled`]. For what a callee or an `extends` target is: OXC 0.159 keeps `(f<T>)(x)` and `extends (B<T>)` as an
97	/// instantiation node beneath the call or heritage clause, where 0.158 moved its type arguments onto them.
98	pub(super) fn peel<'a, 'b>(mut expr: &'b Expression<'a>) -> Peeled<'b, 'a> {
99	    let mut type_arguments = None;
100	    let mut asserted = false;
101	    loop {
102	        expr = match wrapper(expr) {
103	            Some(Wrapper::Transparent(inner)) => inner,
104	            Some(Wrapper::Asserted(inner)) => {
105	                asserted = true;
106	                inner
107	            }
108	            Some(Wrapper::Instantiation(instantiation)) => {
109	                if !asserted && type_arguments.is_none() {
110	                    type_arguments = Some(&*instantiation.type_arguments);
111	                }
112	                &instantiation.expression
113	            }
114	            None => return Peeled { expr, type_arguments },
115	        };
116	    }
117	}
118	
119	/// What a call invokes: `(forwardRef as F)(…)` and `(forwardRef<R, P>)(…)` call `forwardRef`.
120	pub(super) fn callee_of<'a, 'b>(call: &'b CallExpression<'a>) -> &'b Expression<'a> {
121	    peel(&call.callee).expr
122	}
123	
124	/// The type arguments a call is made with: its own, or those of the instantiation it calls (`(forwardRef<R, P>)(…)`).
125	pub(super) fn call_type_arguments<'a, 'b>(
126	    call: &'b CallExpression<'a>,
127	) -> Option<&'b TSTypeParameterInstantiation<'a>> {
128	    call.type_arguments.as_deref().or_else(|| peel(&call.callee).type_arguments)
129	}
130	
131	/// What a class extends and the type arguments it extends it with: `extends React.Component<P>` and
132	/// `extends (React.Component<P>)` both give `React.Component` and `P`.
133	pub(super) fn super_class<'a, 'b>(class: &'b Class<'a>) -> Option<Peeled<'b, 'a>> {
134	    let heritage = class.heritage.as_ref()?;
135	    let peeled = peel(&heritage.expression);
136	    Some(Peeled { expr: peeled.expr, type_arguments: heritage.type_arguments.as_deref().or(peeled.type_arguments) })
137	}
138	
139	/// What a call wrapping an aliased component is, as read from the call before the component is known.
140	#[derive(Clone, Copy)]
141	pub(crate) struct AliasCall {
142	    /// The call follows the component-wrapper conventions (`memo`, `withX(...)`, `forwardRef`, ...).
143	    wrapper: bool,
144	    forward_ref: bool,
145	}
146	
147	/// An alias of a component that was not collected yet when the alias was read.
148	pub(crate) struct PendingAlias {
