70	/// How strongly the first argument says the call builds a component.
71	enum ArgumentEvidence {
72	    Sufficient,
73	    /// A tag name with no element type argument: a component only if a type argument is a factory payload.
74	    TagNeedsPayload,
75	}
76	
77	/// Evidence that the call builds a component from its first argument: a function that renders (Mantine's
78	/// `factory<F>((props) => <Box />)`), a tag name next to an element type argument (`withContext<HTMLDivElement, P>("div")`)
79	/// or a factory payload (`tableElement<TableTrFactory>("tr")`), a reference to a component
80	/// (`withRootProvider<P>(Ark.Root)`), or a wrapped component (`polymorphic<P>(forwardRef(...))`). A tag string alone
81	/// also describes `makeLabel<P>("button")`, and a lowercase value describes a context default or a store, so neither
82	/// counts.
83	fn component_argument_evidence(
84	    creates_context: bool,
85	    call: &CallExpression<'_>,
86	    react: ReactBinding<'_>,
87	) -> Result<ArgumentEvidence, &'static str> {
88	    if creates_context {
89	        return Err("creates a context");
90	    }
91	    let Some(first) = call.arguments.first().and_then(Argument::as_expression).map(super::component::peel_expr) else {
92	        return Err("has no argument that could be a component");
93	    };
94	    let element_type_arg =
95	        || super::component::call_type_arguments(call).is_some_and(|a| a.params.iter().any(is_element_type_arg));
96	    let sufficient = |r: Result<(), &'static str>| r.map(|()| ArgumentEvidence::Sufficient);
97	    match first {
98	        Expression::ArrowFunctionExpression(f) => sufficient(
99	            renders(&FunctionShape::of_arrow(f), react).map_err(|_why| "is given a function that never renders"),
100	        ),
101	        Expression::FunctionExpression(f) => sufficient(
102	            renders(&FunctionShape::of_function(f), react).map_err(|_why| "is given a function that never renders"),
103	        ),
104	        Expression::StringLiteral(_) if element_type_arg() => Ok(ArgumentEvidence::Sufficient),
105	        Expression::StringLiteral(_) => Ok(ArgumentEvidence::TagNeedsPayload),
106	        Expression::Identifier(id) if is_component_reference(id.name.as_str()) => Ok(ArgumentEvidence::Sufficient),
107	        Expression::StaticMemberExpression(m) if is_component_reference(m.property.name.as_str()) => {
108	            Ok(ArgumentEvidence::Sufficient)
109	        }
110	        Expression::CallExpression(inner) if super::component::is_component_wrapper(react, inner) => {
111	            Ok(ArgumentEvidence::Sufficient)
112	        }
113	        _ => Err("is given an argument that is not a render function, a tag or a component reference"),
114	    }
115	}
