236	    /// Turn the recorded candidates into mappings, now that every declaration in the file is known.
237	    pub(super) fn promote_wrapper_calls(&mut self) {
238	        let pending_wrappers = std::mem::take(&mut self.pending_wrappers);
239	        let tag_uses =
240	            |tag: &str| pending_wrappers.iter().filter(|pending| pending.tag.as_deref() == Some(tag)).count();
241	        let shared_tags: Vec<bool> = pending_wrappers
242	            .iter()
243	            .map(|pending| pending.tag.as_deref().is_some_and(|tag| tag_uses(tag) > 1))
244	            .collect();
245	        // A tagged factory takes the props type no other component in the file takes, so every other candidate is
246	        // promoted first, in source order: `StyledGroup = chakra("div", …)` comes before `Group = withContext<…,
247	        // GroupProps>(StyledGroup)` and would otherwise take `GroupProps` before `Group` claims it.
248	        let (tagged, others): (Vec<_>, Vec<_>) =
249	            pending_wrappers.into_iter().zip(shared_tags).partition(|(pending, _)| pending.tag.is_some());
250	        for (pending, shared_tag) in others.into_iter().chain(tagged) {
251	            // The anonymous default export is no binding of its name, so a binding of that name is no reason to skip it.
252	            let bound = self.anonymous_default != Some(pending.span.start);
253	            if bound && self.data.component_mappings.iter().any(|m| m.is_binding_named(&pending.name)) {
254	                continue;
255	            }
256	            if let Some(tag) = &pending.tag {
257	                let Some((props_name, props_args)) = self.tagged_factory_props(&pending.name, tag, shared_tag) else {
258	                    self.record_skip(
259	                        DiagnosticCode::SkippedCandidate,
260	                        format!(
261	                            "'{}' is built from a tag and a config object, but no props type declared in this file gives the tag \"{tag}\"",
262	                            pending.name
263	                        ),
264	                        pending.span,
265	                    );
266	                    continue;
267	                };
268	                self.data.component_mappings.push(
269	                    ComponentMapping::new(
270	                        pending.name,
271	                        props_name,
272	                        self.file_path.clone(),
273	                        pending.span.start,
274	                        pending.span.end,
275	                        pending.rule,
276	                    )
277	                    .with_props_type_args(props_args)
278	                    .with_doc(pending.description, pending.tags),
279	                );
280	                continue;
281	            }
282	            let selected = match self.select_wrapper_props(&pending.type_args) {
283	                PropsSelection::Found { name, args, from_payload } if from_payload || !pending.needs_payload => {
284	                    Some((name, args))
285	                }
286	                PropsSelection::UnusablePayload { alias } => {
287	                    self.record_skip(
288	                        DiagnosticCode::SkippedCandidate,
289	                        format!(
290	                            "'{}' is built from the factory payload '{alias}', whose `props` member is not a named type",
291	                            pending.name
292	                        ),
293	                        pending.span,
294	                    );
295	                    continue;
296	                }
297	                PropsSelection::Found { .. } | PropsSelection::None => None,
298	            };
299	            let Some((props_name, props_args)) = selected else {
300	                self.record_skip(
301	                    DiagnosticCode::SkippedCandidate,
302	                    format!(
303	                        "'{}' looks like a component built by a wrapper call, but none of its type arguments names {}",
304	                        pending.name,
305	                        if pending.needs_payload {
306	                            "a factory payload, which a tag-name argument needs"
307	                        } else {
308	                            "a props type declared in this file or ending in Props"
309	                        }
310	                    ),
311	                    pending.span,
312	                );
313	                continue;
314	            };
315	            let mut mapping = ComponentMapping::new(
316	                pending.name,
317	                props_name,
318	                self.file_path.clone(),
319	                pending.span.start,
320	                pending.span.end,
321	                pending.rule,
322	            )
323	            .with_props_type_args(props_args)
324	            .with_doc(pending.description, pending.tags);
325	            if let Some(callee) = pending.callee {
326	                mapping = mapping.with_wrapper_callee(callee);
327	            }
328	            if !bound {
329	                mapping = mapping.without_binding();
330	            }
