336	    /// gives the factory's tag as a type argument, `interface CenterProps extends HTMLChakraProps<"div">` for
337	    /// `chakra("div", …)`, or extends the element's own attributes. Of several, or when other factories in the file
338	    /// share the tag, the one named for the binding. A props type another component in the file takes is not a candidate.
339	    fn tagged_factory_props(
340	        &self,
341	        binding: &str,
342	        tag: &str,
343	        shared_tag: bool,
344	    ) -> Option<(TypeName, Vec<CollectedType>)> {
345	        let prefix = format!("{}:", self.file_path);
346	        let mut found: Vec<TypeName> = Vec::new();
347	        for interface in self.data.interfaces.values().filter(|interface| interface.file_path == self.file_path) {
348	            if interface.extends.iter().any(|extends| extends_gives_tag(extends, tag)) {
349	                found.push(interface.name.clone());
350	            }
351	        }
352	        for (key, alias) in &self.data.type_aliases {
353	            let Some(name) = key.strip_prefix(&prefix) else { continue };
354	            if alias_gives_tag(alias, tag) {
355	                found.push(TypeName::from(name));
356	            }
357	        }
