359	        // chakra("div", …)` is the private recipe `Group` is built on, not a component with `GroupProps`.
360	        found.retain(|name| !self.data.component_mappings.iter().any(|mapping| mapping.props_type_name == *name));
361	        found.sort();
362	        found.dedup();
363	        let wanted = format!("{binding}Props");
364	        let chosen = match found.as_slice() {
365	            [only] if !shared_tag => only.clone(),
366	            _ => found.into_iter().find(|name| name.as_str() == wanted)?,
367	        };
368	        Some((chosen, Vec::new()))
369	    }
