413	    fn record_result_of<'a>(
414	        &mut self,
415	        name: &str,
416	        type_parameters: Option<&TSTypeParameterDeclaration<'a>>,
417	        return_type: Option<&TSTypeAnnotation<'a>>,
418	        body: Option<&FunctionBody<'a>>,
419	    ) {
420	        let generic = type_parameters.is_some();
421	        let declared = return_type.is_some();
422	        let (result, returned_call) = if let Some(annotation) = return_type {
423	            if !generic {
424	                return;
425	            }
426	            (self.ts_type_to_collected(&annotation.type_annotation), None)
427	        } else if let Some(ty) = asserted_return_type(body).filter(|_| generic) {
428	            (self.ts_type_to_collected(ty), None)
429	        } else if let Some(ty) = returned_local_asserted(body) {
430	            (self.ts_type_to_collected(ty), None)
431	        } else if let Some(function_type) = self.returned_rendering_function(body) {
432	            (function_type, None)
433	        } else if generic {
434	            (CollectedType::Unknown, returned_local_call(self, body))
435	        } else {
436	            return;
437	        };
438	        if matches!(result, CollectedType::Unknown) && returned_call.is_none() {
439	            return;
440	        }
441	        let type_params = super::type_param_names(type_parameters);
442	        let key = self.scoped_key(name);
443	        // A declared result type is written around the function; every other result is read from its body, whose
444	        // scope is known once the body has been walked (`finish`).
445	        let mut scope = self.current_scope();
446	        self.body_result_keys.retain(|(recorded, _)| *recorded != key);
447	        if let (false, Some(body)) = (declared, body) {
448	            self.body_result_keys.push((key.clone(), body.span.start));
449	            scope = DeclarationScope::default();
450	        }
451	        self.data.function_results.insert(key, FunctionResult { type_params, result, returned_call, scope });
452	    }
