454	    /// A single top-level `return function Loader(props: Props) { ... }` or `return (props: Props) => ...` that
455	    /// renders: a component built by the function, with a function type whose first parameter is the props.
456	    fn returned_rendering_function<'a>(&mut self, body: Option<&FunctionBody<'a>>) -> Option<CollectedType> {
457	        let mut returns = body?.statements.iter().filter_map(|statement| match statement {
458	            Statement::ReturnStatement(ret) => ret.argument.as_ref(),
459	            _ => None,
460	        });
461	        let only = returns.next()?;
462	        if returns.next().is_some() {
463	            return None;
464	        }
465	        let (params, shape) = match only.without_parentheses() {
466	            Expression::FunctionExpression(f) => (&f.params, FunctionShape::of_function(f)),
467	            Expression::ArrowFunctionExpression(f) => (&f.params, FunctionShape::of_arrow(f)),
468	            _ => return None,
469	        };
470	        let annotation = params.items.first()?.type_annotation.as_ref()?;
471	        if renders(&shape, &*self).is_err() {
472	            return None;
473	        }
474	        let props = self.ts_type_to_collected(&annotation.type_annotation);
475	        Some(CollectedType::Function {
476	            type_params: Vec::new(),
477	            params: vec![props],
478	            param_names: vec![None],
479	            param_kinds: Vec::new(),
480	            return_type: Box::new(CollectedType::Unknown),
481	        })
482	    }
