/// Finding A: `Object.assign` through an identity cast makes `Root` an alias of `Impl`, and the inline member scan reads
/// the call through the same predicate, so `Item` is found too. A cast to a type that is not `Object`'s finds neither.
#[test]
fn an_object_assign_through_an_identity_cast_attaches_its_inline_members() {
    let found = |object: &str| {
        let source = format!(
            "interface P {{ a: string }}\\n\\
             interface ItemProps {{ b: string }}\\n\\
             function Impl(props: P) {{ return <div />; }}\\n\\
             export const Root = {object}.assign(Impl, {{ Item: (props: ItemProps) => <div /> }});"
        );
        let data = parse_file(Utf8Path::new("/test/compound.tsx"), &source);
        let mut found: Vec<(String, String)> = data
            .component_mappings
            .iter()
            .map(|m| (m.component_name.clone(), m.props_type_name.to_string()))
            .collect();
        found.sort_unstable();
        found
    };
    let both = [("Impl".to_owned(), "P".to_owned()), ("Item".into(), "ItemProps".into()), ("Root".into(), "P".into())];
    for object in ["Object", "(Object as typeof Object)", "(Object as any)", "(<typeof Object>Object)"] {
        if object.starts_with("(<") {
            continue; // `<T>x` is JSX in a `.tsx` file.
        }
        assert_eq!(found(object), both, "{object}");
    }
    assert_eq!(found("(Object as object)"), [("Impl".to_owned(), "P".to_owned())]);
}

/// Finding B: a PascalCase callee is rendering evidence only while its name describes the call. An assertion that
/// gives the call a plain-object result takes that away; a named or React result, `typeof` itself and `any` keep it.
#[test]
fn an_asserted_callee_renders_only_when_the_assertion_leaves_a_named_result() {
    let rows = [
        ("(Object as (value: object) => object)", false),
        ("(Object as unknown as (value: object) => string)", false),
        ("(Object as { (value: object): object })", false),
        ("(Object as (value: object) => React.ReactElement)", true),
        ("(Object as (value: object) => React.ReactElement | null)", true),
        ("(Object as F)", true),
        ("(Object as typeof Object)", true),
        ("(Object as any)", true),
        ("Object", true),
    ];
    for (callee, renders) in rows {
        let source = format!(
            "import React from 'react';\\n\\
             interface Props {{ a: string }}\\n\\
             export const Normalize = (props: Props) => {callee}(props);"
        );
        let data = parse_file(Utf8Path::new("/test/normalize.tsx"), &source);
        let names: Vec<&str> = data.component_mappings.iter().map(|m| m.component_name.as_str()).collect();
        let expected: &[&str] = if renders { &["Normalize"] } else { &[] };
        assert_eq!(names, expected, "{callee}");
    }
}

