        let component = &output.components["Wrapped"];
        component.props.keys().cloned().collect::<Vec<String>>()
    };
    assert_eq!(props_of("(wrap as <T>(render: React.FC<T>) => React.FC<T>)<Props>"), ["label"]);
    assert_eq!(props_of("(<T>(render: React.FC<T>) => React.FC<T>>wrap)<Props>".replace("(<T>", "(<<T>").as_str()).len(), 0);
