/// A PascalCase callee is rendering evidence only while its name describes the call: an assertion stating a result
/// that is no named type takes it away; a named or React result, `typeof` itself and `any` leave it.
#[test]
fn an_asserted_callee_renders_only_when_the_assertion_leaves_a_named_result() {
    let rows = [
        ("(Object as (value: object) => object)", false),
        ("(Object as unknown as (value: object) => string)", false),
        ("(Object as { (value: object): object })", false),
        ("(Object as (value: object) => React.ReactElement)", true),
        ("(Object as (value: object) => React.ReactElement | null)", true),
        ("(Object as F)", true),
        ("(Object as typeof Object)", true),
        ("(Object as any)", true),
        ("Object", true),
    ];
    for (callee, renders) in rows {
        let source = format!(
            "import React from 'react';\n\
             interface Props {{ a: string }}\n\
             export const Normalize = (props: Props) => {callee}(props);"
        );
        let data = parse_file(Utf8Path::new("/test/normalize.tsx"), &source);
        let names: Vec<&str> = data.component_mappings.iter().map(|m| m.component_name.as_str()).collect();
        let expected: &[&str] = if renders { &["Normalize"] } else { &[] };
        assert_eq!(names, expected, "{callee}");
    }
}

/// A generic wrapper asserted to another signature does not carry its original declaration, whose result would add
/// `internal`: the props are the render function's. Unasserted, or asserted to `typeof` itself, the declaration is read.
#[test]
fn an_asserted_wrapper_callee_does_not_resolve_through_its_original_declaration() {
    let props_of = |call: &str| {
        let tmp = tempfile::TempDir::new_in(Utf8Path::new(env!("CARGO_MANIFEST_DIR"))).unwrap();
        let source = format!(
            "import * as React from 'react';\n\
             function wrap<T>(render: React.FC<T>): React.FC<T & {{ internal?: string }}> {{ return render as any; }}\n\
             interface Props {{ label?: string }}\n\
             export const Wrapped = {call}((props: Props) => <div />);\n"
        );
        std::fs::write(tmp.path().join("Wrapped.tsx"), source).unwrap();
        let root = Utf8PathBuf::from_path_buf(tmp.path().to_owned()).unwrap();
        let options = crate::pipeline::PipelineOptions {
            src_dirs: vec![root.clone()],
            cache_dir: Some(root.join("cache")),
            ..Default::default()
        };
        let output = crate::pipeline::extract(&options);
        output.components["Wrapped"].props.keys().cloned().collect::<Vec<String>>()
    };
    assert_eq!(props_of("(wrap as <T>(render: React.FC<T>) => React.FC<T>)<Props>"), ["label"]);
    assert_eq!(props_of("wrap<Props>"), ["internal", "label"]);
    assert_eq!(props_of("(wrap as typeof wrap)<Props>"), ["internal", "label"]);
}

